findings.codeql_raw_query:
/**
 * @name SQL injection via string-formatted queries
 * @description Detects untrusted data flowing into cursor.execute() and similar Snowflake query APIs without parameterization.
 * @kind path-problem
 * @problem.severity error
 * @id py/snowflake-connector/sql-injection
 * @tags security
 *       external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SnowflakeSQLConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // snowflake.connector.cursor.Cursor.execute / executemany / execute_async
      call = API::moduleImport("snowflake.connector.cursor").getMember("Cursor!").getMember(["execute", "executemany", "execute_async"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SnowflakeSQLFlow = TaintTracking::Global<SnowflakeSQLConfig>;
import SnowflakeSQLFlow::PathGraph

from SnowflakeSQLFlow::PathNode source, SnowflakeSQLFlow::PathNode sink
where SnowflakeSQLFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Remote input reaches SQL execution in Snowflake cursor $@.", source.getNode(), "remote input"
